import{_ as n,a0 as p,w as i,s as d,ao as r,I as l,x as e,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"Linux有問必答：如何在命令列創建一個MySQL資料庫 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在命令列創建一個MySQL資料庫 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在命令列創建一個MySQL資料庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在命令列創建一個MySQL資料庫 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line","title":"Linux有問必答：如何在命令列創建一個MySQL資料庫","tag":"201410","desc":""},"relativePath":"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line.md","filePath":"[post].md"}'),m={name:"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line.md"};function L(u,t,y,T,S,_){const a=p("Link");return i(),d("div",null,[t[16]||(t[16]=r(`<h1 id="linux有問必答-如何在命令列創建一個mysql資料庫" tabindex="-1">Linux有問必答：如何在命令列創建一個MySQL資料庫 <a class="header-anchor" href="#linux有問必答-如何在命令列創建一個mysql資料庫" aria-label="Permalink to “Linux有問必答：如何在命令列創建一個MySQL資料庫”">​</a></h1><blockquote><p><strong>問題</strong>：在一個某處運行的MySQL服務器上，我該怎樣通過命令列創建和安裝一個MySQL資料庫呢？</p></blockquote><p>為了能通過命令列創建一個MySQL資料庫，你可以使用mysql命令列客户端。下面是通過mysql命令列客户端創建和安裝MySQL的步驟。</p><h3 id="第一步-安裝mysql客户端" tabindex="-1">第一步：安裝MySQL客户端 <a class="header-anchor" href="#第一步-安裝mysql客户端" aria-label="Permalink to “第一步：安裝MySQL客户端”">​</a></h3><p>當然你得確保MySQL客户端已經安裝完畢。如果沒有的話，可以按照下面的方法。</p><p>在Debian，Ubuntu 或者 Linux Mint上：</p><pre><code>$ sudo apt-get install mysql-client
</code></pre><p>在Fedora，CentOS 或者 RHEL上：</p><pre><code>$ sudo apt-get install mysql
</code></pre><h3 id="第二步-登陸到mysql服務器" tabindex="-1">第二步：登陸到MySQL服務器 <a class="header-anchor" href="#第二步-登陸到mysql服務器" aria-label="Permalink to “第二步：登陸到MySQL服務器”">​</a></h3><p>首先，你需要使用root用户登陸進你的MySQL資料庫，如下：</p><pre><code>$ mysql -u root -h &lt;mysql-server-ip-address&gt; -p 
</code></pre>`,12)),l("p",null,[t[1]||(t[1]=e("請注意：為了能登進遠程的MySQL服務器，你需要",-1)),s(a,{href:"http://xmodulo.com/2012/06/how-to-allow-remote-access-to-mysql.html"},{default:o(()=>[...t[0]||(t[0]=[e("開啓服務器上的遠程訪問",-1)])]),_:1}),t[2]||(t[2]=e("，如果你想調用同一主機上的MySQL服務器，你可以省略 ",-1)),t[3]||(t[3]=l("code",null,"-h <mysql-server-ip-address>",-1)),t[4]||(t[4]=e(" 參數",-1))]),t[17]||(t[17]=r(`<pre><code>$ mysql -u root -p
</code></pre><p>你將需要輸入MySQL服務器的密碼，如果認證成功，MySQL提示將會出現。</p><p><img src="https://www.flickr.com/photos/xmodulo/15272971112/" alt=""></p><h3 id="第三步-創建一個mysql資料庫" tabindex="-1">第三步：創建一個MySQL資料庫 <a class="header-anchor" href="#第三步-創建一個mysql資料庫" aria-label="Permalink to “第三步：創建一個MySQL資料庫”">​</a></h3><p>在MySQL提示中輸入命令之前，請記住所有的命令都是以分號結束的(否則將不會執行)。另外，考慮輸入命令的時候使用大些字母，輸入資料庫對象使用小寫字母。但那不是必須的，只是方便你的閲讀。</p><p>現在，讓我們創建一個叫做xmodulo_DB的資料庫：</p><pre><code>mysql&gt; CREATE DATABASE IF NOT EXISTS xmodulo_DB; 
</code></pre><p><img src="https://farm4.staticflickr.com/3864/15086792487_8e2eaedbcd.jpg" alt=""></p><h3 id="第四步-創建一個數據庫表" tabindex="-1">第四步：創建一個數據庫表 <a class="header-anchor" href="#第四步-創建一個數據庫表" aria-label="Permalink to “第四步：創建一個數據庫表”">​</a></h3><p>為了達到演示的目的，我們將會創建一個叫做posts_tbl的表，表裏會存儲關於文章的如下信息：</p><ul><li>文章的標題</li><li>作者的名字</li><li>作者的姓</li><li>文章可用或者不可用</li><li>文章創建的日期</li></ul><p>這個過程分兩步執行：</p><p>首先，選擇我們需要使用的資料庫：</p><pre><code>mysql&gt; USE xmodulo_DB; 
</code></pre><p>然後，在資料庫中創建新表：</p><pre><code>mysql&gt; CREATE TABLE &#39;posts_tbl&#39; (
&#39;post_id&#39; INT UNSIGNED NOT NULL AUTO_INCREMENT, 
&#39;content&#39; TEXT,
&#39;author_FirstName&#39; VARCHAR(100) NOT NULL,
&#39;author_LastName&#39; VARCHAR(50) DEFAULT NULL ,
&#39;isEnabled&#39; TINYINT(1) NOT NULL DEFAULT 1, 
&#39;date&#39; TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ,
PRIMARY KEY ( &#39;post_id&#39; ) 
) TYPE = MYISAM;
</code></pre><p><img src="https://farm4.staticflickr.com/3870/15086654980_39d2d54d72.jpg" alt=""></p><h3 id="第五步-創建一個用户-並授予權限" tabindex="-1">第五步：創建一個用户，並授予權限 <a class="header-anchor" href="#第五步-創建一個用户-並授予權限" aria-label="Permalink to “第五步：創建一個用户，並授予權限”">​</a></h3><p>當涉及到訪問我們新創的資料庫和表的時候，創建一個新用户是一個很好的主意。這樣做就可以讓用户在沒有整個MySQL服務器權限的情況下，去訪問那個資料庫(而且只能是那個資料庫)</p><p>你可以創建新用户，授予權限，並且使改變生效：</p><pre><code>mysql&gt; GRANT ALL PRIVILEGES ON xmodulo_DB.* TO &#39;new_user&#39;@&#39;%&#39; IDENTIFIED BY &#39;new_password&#39;;
mysql&gt; FLUSH PRIVILEGES;
</code></pre><p>&#39;new_user&#39;和&#39;new_password&#39;分別指的是新的用户名和他的密碼。這條信息將會被保存在mysql.user表中，而且密碼會被加密。</p><h3 id="第六步-測試" tabindex="-1">第六步：測試 <a class="header-anchor" href="#第六步-測試" aria-label="Permalink to “第六步：測試”">​</a></h3><p>讓我們插入一個虛擬的記錄到posts_tbl表：</p><pre><code>mysql&gt; USE xmodulo_DB;
mysql&gt; INSERT INTO posts_tbl (content, author_FirstName, author_Las tName)
VALUES (&#39;Hi! This is some dummy text.&#39;, &#39;Gabriel&#39;, &#39;Canepa&#39;);
</code></pre><p>然後查看posts_tbl表中的所有記錄：</p><pre><code>mysql&gt; SELECT * FROM posts_tbl;
</code></pre><p><img src="https://farm4.staticflickr.com/3896/15086792527_39a987d8bd_z.jpg" alt=""></p><p>注意：MySQL會在我們先前定義的地方自動插入適當的默認值(比如，&#39;isEnabled&#39;和&#39;date&#39;)。</p><hr>`,30)),l("p",null,[t[6]||(t[6]=e("via: ",-1)),s(a,{href:"http://ask.xmodulo.com/create-mysql-database-command-line.html"},{default:o(()=>[...t[5]||(t[5]=[e("http://ask.xmodulo.com/create-mysql-database-command-line.html",-1)])]),_:1})]),l("p",null,[t[9]||(t[9]=e("譯者：",-1)),s(a,{href:"https://github.com/su-kaiyao"},{default:o(()=>[...t[7]||(t[7]=[e("su-kaiyao",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),s(a,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linu x中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const f=n(m,[["render",L]]);export{M as __pageData,f as default};
